Method.Implementation:
	#dim tSC=$$$OK
	// Attribute to search on
	#dim pAttr="ihc4medica"
	#dim pSearchLevel=1	
	//Search for the key
	#dim pFilterconstant="providerid"
	//Ldap search return is of type %Net.LDAP.Client.Entries
	#dim pEntries As %Net.LDAP.Client.Entries
	#dim ldapEntry As %Net.LDAP.Client.Entry
	#dim valueList As %Net.LDAP.Client.ValueList
	// Parameter to be passed to Ldap Search API
	#dim pFilterString As %String=pFilterconstant_"="_pRequest.StringValue

	#dim keyEntries,keyEntry,keyValueList As %String=""
	#dim attrValue As %String=""


	set pResponse=##class(Ens.StringResponse).%New()
	set pResponse.StringValue=""

	$$$TRACE(" Filter "_pFilterString)

	// Call LDAP search
	set tSC=..Adapter.Search(.pEntries,pSearchLevel,pFilterString,pAttr)
	$$$TRACE(" Returned Status "_tSC)


	if (tSC){

		$$$TRACE(" PENTRIES *"_$G(pEntries,"Default")_"*")
		set keyEntries="" 
		 do {
			 set ldapEntry=pEntries.GetNext(.keyEntries)
		  	 $$$TRACE(" Got LDAP Entry "_ldapEntry_" keyEntries `"_keyEntries)
		  	 quit:keyEntries=""
		  	 set keyEntry=""
		 	 do  {
			 	 set valueList=ldapEntry.GetNext(.keyEntry)
			 	 quit:keyEntry=""
				 $$$TRACE(" ValueList "_valueList_" for key "_keyEntry)
				 set keyValueList=""
				 do  {	  
				 	set attrValue=valueList.GetNext(.keyValueList)
			        quit:keyValueList=""
			        $$$TRACE(" VALUE "_attrValue)
			        if (keyEntry=pAttr){
				        s pResponse.StringValue=attrValue
				        quit
			        }
			        $$$TRACE(" level1 "_key_" level 2 "_k1_" level3key "_k2_" Value "_value)
			     }while (keyValueList'="")
		 	 }while (keyEntry'="")

		 }while (keyEntries'="")
	quit tSC
}
